import type { MotionPersonality } from './types.js';

/**
 * Hand-written prose snippets per preset. Loaded by section. Keeping these
 * static (rather than runtime-generated by a model) so the DESIGN.md output is
 * deterministic across builds and CI snapshot tests stay stable.
 */

export interface PresetProse {
  /** One paragraph for the Overview section. Brand voice. */
  overview: string;
  /** Motion personality classification. Drives the Motion section. */
  motionPersonality: MotionPersonality;
  /** One sentence describing the density / element rhythm. */
  density: string;
}

