export function getPresetProse(presetName: string): PresetProse {
  return PRESETS[presetName] ?? FALLBACK;
}

export function describeMotionPersonality(personality: MotionPersonality): string {
  switch (personality) {
    case 'calm':
      return 'Calm: durations slightly longer than default, easings lean ease-in-out. Reveals settle rather than snap.';
    case 'snappy':
      return 'Snappy: shorter durations, sharper easings. Interactions confirm immediately; nothing lingers.';
    case 'static':
      return 'Static: motion is disabled at the component level. Hover and focus states use color only, no transition.';
    case 'spring':
      return 'Spring: cubic-bezier easings overshoot the target slightly before settling. Reads as kinetic.';
    case 'step':
      return 'Step: easings use steps() for a chunky, retro feel. Transitions appear in discrete frames rather than smoothly.';
    case 'organic':
      return 'Organic: spring easings paired with slightly elongated durations. Motion feels breathed rather than mechanical.';
    case 'languid':
      return 'Languid: longer durations, ease-in-out only. Best for content-forward interfaces with translucent surfaces.';
    default:
      return 'Default: balanced durations and easings. Suitable for productivity and marketing surfaces alike.';
  }
}
